/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
// Exports the contents of a grid (using the selected order and filters) to an Excel file. LoadWWPContext.Call(&WWPContext)
Do 'OpenDocument'
&CellRow = 1 &FirstColumn = 1
Do 'LoadGridState'
Do 'WriteFilters'
Do 'WriteColumnTitles'
Do 'WriteData'
Do 'CloseDocument'
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
Sub 'OpenDocument'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&Random = Random() * 10000 &Filename = WWP_GetDefaultExportPath() + !"trnsremessaprodutoWWExport-" + &Random.ToString().Trim() + !".xlsx"
&ExcelDocument.Open(&Filename) Do 'CheckStatus' &ExcelDocument.Clear()
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'WriteFilters'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
If &GridState.DynamicFilters.Count >= 1 &GridStateDynamicFilter = &GridState.DynamicFilters.Item(1) &DynamicFiltersSelector1 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector1 = !'REMPRODDESCRICAO' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &remProdDescricao1.FromString(&GridStateDynamicFilter.Value) If not &remProdDescricao1.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator1 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Descrição", "WWP_FilterLike") Case &DynamicFiltersOperator1 = 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Descrição", "WWP_FilterContains") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&remProdDescricao1) EndIf EndCase If &GridState.DynamicFilters.Count >= 2 &DynamicFiltersEnabled2 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(2) &DynamicFiltersSelector2 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector2 = !'REMPRODDESCRICAO' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &remProdDescricao2.FromString(&GridStateDynamicFilter.Value) If not &remProdDescricao2.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator2 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Descrição", "WWP_FilterLike") Case &DynamicFiltersOperator2 = 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Descrição", "WWP_FilterContains") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&remProdDescricao2) EndIf EndCase If &GridState.DynamicFilters.Count >= 3 &DynamicFiltersEnabled3 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(3) &DynamicFiltersSelector3 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector3 = !'REMPRODDESCRICAO' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &remProdDescricao3.FromString(&GridStateDynamicFilter.Value) If not &remProdDescricao3.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator3 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Descrição", "WWP_FilterLike") Case &DynamicFiltersOperator3 = 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Descrição", "WWP_FilterContains") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&remProdDescricao3) EndIf EndCase EndIf EndIf EndIf If not (&TFremProdCodigo.IsEmpty() AND &TFremProdCodigo_To.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Código") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Number = &TFremProdCodigo WWP_ExportWriteFilter(&ExcelDocument, false, &CellRow, &FirstColumn + 2, "WWP_TSTo") &ExcelDocument.Cells(&CellRow, &FirstColumn + 3).Number = &TFremProdCodigo_To EndIf If not (&TFremProdDescricao_Sel.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Descrição") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&TFremProdDescricao_Sel) Else If not (&TFremProdDescricao.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Descrição") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&TFremProdDescricao) EndIf EndIf If not (&TFremProdUnPeso_Sel.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Unidade") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&TFremProdUnPeso_Sel) Else If not (&TFremProdUnPeso.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Unidade") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&TFremProdUnPeso) EndIf EndIf If not (&TFremProdAreEnsCodigo_Sel.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Área") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = &TFremProdAreEnsCodigo_SelDsc
Else If not (&TFremProdAreEnsCodigo.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Área") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&TFremProdAreEnsCodigo) EndIf EndIf If not (&TFremProdAreEnsSequencial_Sel.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Etapa") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = &TFremProdAreEnsSequencial_SelDsc
Else If not (&TFremProdAreEnsSequencial.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Etapa") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&TFremProdAreEnsSequencial) EndIf EndIf If not (&TFremProdAreEnsTurno_Sels.Count = 0) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Turno") &i = 1 For &TFremProdAreEnsTurno_Sel in &TFremProdAreEnsTurno_Sels If &i = 1 &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = '' Else &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text += ', ' EndIf do Case Case &TFremProdAreEnsTurno_Sel = 1 &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text += "Matutino"
Case &TFremProdAreEnsTurno_Sel = 2 &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text += "Vespertino"
Case &TFremProdAreEnsTurno_Sel = 3 &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text += "Noturno"
Case &TFremProdAreEnsTurno_Sel = 4 &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text += "Integral"
Case &TFremProdAreEnsTurno_Sel = 5 &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text += "Interm. Matutino"
Case &TFremProdAreEnsTurno_Sel = 6 &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text += "Interm. Vespertino"
EndCase &i += 1 EndFor EndIf If not (&TFremProdQtde.IsEmpty() AND &TFremProdQtde_To.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Qtde") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Number = &TFremProdQtde WWP_ExportWriteFilter(&ExcelDocument, false, &CellRow, &FirstColumn + 2, "WWP_TSTo") &ExcelDocument.Cells(&CellRow, &FirstColumn + 3).Number = &TFremProdQtde_To EndIf If not (&TFremProdPerCapta.IsEmpty() AND &TFremProdPerCapta_To.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Capta") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Number = &TFremProdPerCapta WWP_ExportWriteFilter(&ExcelDocument, false, &CellRow, &FirstColumn + 2, "WWP_TSTo") &ExcelDocument.Cells(&CellRow, &FirstColumn + 3).Number = &TFremProdPerCapta_To EndIf &CellRow += 2
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'WriteColumnTitles'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&VisibleColumnCount = 0 If &Session.Get(!'trnsremessaprodutoWWColumnsSelector') <> '' &ColumnsSelectorXML = &Session.Get(!'trnsremessaprodutoWWColumnsSelector') &ColumnsSelector.FromXml(&ColumnsSelectorXML) Else Do 'InitializeColumnsSelector' EndIf
&ColumnsSelector.Columns.Sort(!'Order') For &ColumnsSelector_Column in &ColumnsSelector.Columns If &ColumnsSelector_Column.IsVisible = True &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Text = GetMessageText(iif(&ColumnsSelector_Column.DisplayName.IsEmpty(), &ColumnsSelector_Column.ColumnName, &ColumnsSelector_Column.DisplayName)) &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Color = 11 &VisibleColumnCount += 1 EndIf EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'WriteData'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
For each trnsremessaproduto order prefCodigo remCodigo remProdDescricao when &OrderedBy = 1 AND &OrderedDsc = False order (prefCodigo) (remCodigo) (remProdDescricao) when &OrderedBy = 1 AND &OrderedDsc = True order prefCodigo remCodigo remProdCodigo when &OrderedBy = 2 AND &OrderedDsc = False order (prefCodigo) (remCodigo) (remProdCodigo) when &OrderedBy = 2 AND &OrderedDsc = True order prefCodigo remCodigo remProdUnPeso when &OrderedBy = 3 AND &OrderedDsc = False order (prefCodigo) (remCodigo) (remProdUnPeso) when &OrderedBy = 3 AND &OrderedDsc = True order prefCodigo remCodigo remProdAreEnsCodigo when &OrderedBy = 4 AND &OrderedDsc = False order (prefCodigo) (remCodigo) (remProdAreEnsCodigo) when &OrderedBy = 4 AND &OrderedDsc = True order prefCodigo remCodigo remProdAreEnsSequencial when &OrderedBy = 5 AND &OrderedDsc = False order (prefCodigo) (remCodigo) (remProdAreEnsSequencial) when &OrderedBy = 5 AND &OrderedDsc = True order prefCodigo remCodigo remProdAreEnsTurno when &OrderedBy = 6 AND &OrderedDsc = False order (prefCodigo) (remCodigo) (remProdAreEnsTurno) when &OrderedBy = 6 AND &OrderedDsc = True order prefCodigo remCodigo remProdQtde when &OrderedBy = 7 AND &OrderedDsc = False order (prefCodigo) (remCodigo) (remProdQtde) when &OrderedBy = 7 AND &OrderedDsc = True order prefCodigo remCodigo remProdPerCapta when &OrderedBy = 8 AND &OrderedDsc = False order (prefCodigo) (remCodigo) (remProdPerCapta) when &OrderedBy = 8 AND &OrderedDsc = True
using trnsremessaprodutoWWDS(&prefCodigo, &remCodigo, &DynamicFiltersSelector1, &DynamicFiltersOperator1, &remProdDescricao1, &DynamicFiltersEnabled2 , &DynamicFiltersSelector2, &DynamicFiltersOperator2, &remProdDescricao2, &DynamicFiltersEnabled3, &DynamicFiltersSelector3, &DynamicFiltersOperator3 , &remProdDescricao3, &TFremProdCodigo, &TFremProdCodigo_To, &TFremProdDescricao, &TFremProdDescricao_Sel, &TFremProdUnPeso , &TFremProdUnPeso_Sel, &TFremProdAreEnsCodigo, &TFremProdAreEnsCodigo_Sel, &TFremProdAreEnsSequencial, &TFremProdAreEnsSequencial_Sel, &TFremProdAreEnsTurno_Sels , &TFremProdQtde, &TFremProdQtde_To, &TFremProdPerCapta, &TFremProdPerCapta_To) Where prefCodigo = &prefCodigo
// Write cell values &CellRow += 1
Do 'BeforeWriteLine' &VisibleColumnCount = 0 For &ColumnsSelector_Column in &ColumnsSelector.Columns If &ColumnsSelector_Column.IsVisible = True Do Case Case &ColumnsSelector_Column.ColumnName = !'remProdCodigo' &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Number = remProdCodigo Case &ColumnsSelector_Column.ColumnName = !'remProdDescricao' &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Text = WWP_Export_SecureText(remProdDescricao) Case &ColumnsSelector_Column.ColumnName = !'remProdUnPeso' &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Text = WWP_Export_SecureText(remProdUnPeso) Case &ColumnsSelector_Column.ColumnName = !'remProdAreEnsCodigo' &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Text = WWP_Export_SecureText(AreEnsNome) Case &ColumnsSelector_Column.ColumnName = !'remProdAreEnsSequencial' &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Text = WWP_Export_SecureText(AreEnsEtapaNome) Case &ColumnsSelector_Column.ColumnName = !'remProdAreEnsTurno' &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Text = '' do Case Case remProdAreEnsTurno = 1 &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Text = "Matutino"
Case remProdAreEnsTurno = 2 &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Text = "Vespertino"
Case remProdAreEnsTurno = 3 &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Text = "Noturno"
Case remProdAreEnsTurno = 4 &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Text = "Integral"
Case remProdAreEnsTurno = 5 &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Text = "Interm. Matutino"
Case remProdAreEnsTurno = 6 &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Text = "Interm. Vespertino"
EndCase Case &ColumnsSelector_Column.ColumnName = !'remProdQtde' &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Number = remProdQtde Case &ColumnsSelector_Column.ColumnName = !'remProdPerCapta' &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Number = remProdPerCapta EndCase &VisibleColumnCount += 1 EndIf EndFor
Do 'AfterWriteLine'
Endfor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'CloseDocument'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&ExcelDocument.Save() Do 'CheckStatus' &ExcelDocument.Close() &Session.Set(!'WWPExportFilePath', &Filename) &Session.Set(!'WWPExportFileName', !"trnsremessaprodutoWWExport.xlsx") &Filename = WWP_DownloadReport.Link()
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'CheckStatus'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
If (&ExcelDocument.ErrCode <> 0) &Filename = "" &ErrorMessage = &ExcelDocument.ErrDescription &ExcelDocument.Close() Return EndIf
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'InitializeColumnsSelector'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&ColumnsSelector = new WWPColumnsSelector() WWP_ColumnsSelector_Add(&ColumnsSelector, !"remProdCodigo", '', !'Código', True, '') WWP_ColumnsSelector_Add(&ColumnsSelector, !"remProdDescricao", '', !'Descrição', True, '') WWP_ColumnsSelector_Add(&ColumnsSelector, !"remProdUnPeso", '', !'Unidade', True, '') WWP_ColumnsSelector_Add(&ColumnsSelector, !"remProdAreEnsCodigo", '', !'Área', True, '') WWP_ColumnsSelector_Add(&ColumnsSelector, !"remProdAreEnsSequencial", '', !'Etapa', True, '') WWP_ColumnsSelector_Add(&ColumnsSelector, !"remProdAreEnsTurno", '', !'Turno', True, '') WWP_ColumnsSelector_Add(&ColumnsSelector, !"remProdQtde", '', !'Qtde', True, '') WWP_ColumnsSelector_Add(&ColumnsSelector, !"remProdPerCapta", '', !'Capta', True, '')
&UserCustomValue = LoadColumnsSelectorState.Udp(!'trnsremessaprodutoWWColumnsSelector') If not(&UserCustomValue.IsEmpty()) &ColumnsSelectorAux.FromXml(&UserCustomValue) WWP_ColumnSelector_UpdateColumns(&ColumnsSelectorAux, &ColumnsSelector) EndIf
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'LoadGridState'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
// Load grid state from session. If &Session.Get(!"trnsremessaprodutoWWGridState") = !"" &GridState.FromXml(LoadGridState.Udp(!"trnsremessaprodutoWWGridState")) Else &GridState.FromXml(&Session.Get(!"trnsremessaprodutoWWGridState")) Endif
&OrderedBy = &GridState.OrderedBy &OrderedDsc = &GridState.OrderedDsc
For &GridStateFilterValue in &GridState.FilterValues Do Case Case &GridStateFilterValue.Name = !"TFREMPRODCODIGO" &TFremProdCodigo.FromString(&GridStateFilterValue.Value) &TFremProdCodigo_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFREMPRODDESCRICAO" &TFremProdDescricao.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFREMPRODDESCRICAO_SEL" &TFremProdDescricao_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFREMPRODUNPESO" &TFremProdUnPeso.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFREMPRODUNPESO_SEL" &TFremProdUnPeso_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFREMPRODAREENSCODIGO" &TFremProdAreEnsCodigo.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFREMPRODAREENSCODIGO_SEL" &TFremProdAreEnsCodigo_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFREMPRODAREENSSEQUENCIAL" &TFremProdAreEnsSequencial.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFREMPRODAREENSSEQUENCIAL_SEL" &TFremProdAreEnsSequencial_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFREMPRODAREENSTURNO_SEL" &TFremProdAreEnsTurno_SelsJson = &GridStateFilterValue.Value &TFremProdAreEnsTurno_Sels.FromJson(&TFremProdAreEnsTurno_SelsJson) Case &GridStateFilterValue.Name = !"TFREMPRODQTDE" &TFremProdQtde.FromString(&GridStateFilterValue.Value) &TFremProdQtde_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFREMPRODPERCAPTA" &TFremProdPerCapta.FromString(&GridStateFilterValue.Value) &TFremProdPerCapta_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"PARM_&PREFCODIGO" &prefCodigo.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"PARM_&REMCODIGO" &remCodigo.FromString(&GridStateFilterValue.Value) EndCase EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
